# Review package: d8d9b548836b350f70b0cbf98e337ba6599d282d..a680bcc6c422aefd219891661737a143e980ab6f

## Commits
a680bcc test: cover hyphenated compounds and numbers in topWords

## Files changed
 test/topWords.test.js | 7 +++++++
 1 file changed, 7 insertions(+)

## Diff
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 67a3858..beaa7b1 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -146,10 +146,17 @@ test('returns every distinct word when n exceeds their number', () => {
 test('returns fresh objects on every call', () => {
   const first = topWords('apple apple banana', 2);
   first[0].count = 99;
   first[0].word = 'changed';
   first.pop();
   assert.deepEqual(topWords('apple apple banana', 2), [
     { word: 'apple', count: 2 },
     { word: 'banana', count: 1 },
   ]);
 });
+
+test('keeps hyphenated compounds whole and counts numbers as words', () => {
+  assert.deepEqual(topWords('well-known well-known 42 42 42', 5), [
+    { word: '42', count: 3 },
+    { word: 'well-known', count: 2 },
+  ]);
+});

